const ctx = $('解析事件').first().json;
const resp = $json;

if (resp.code !== 0 && resp.code !== undefined) {
  return [{
    json: {
      ready: false,
      fail_reason: `拉取群消息失败: ${resp.msg || JSON.stringify(resp)}`,
      chat_id: ctx.chat_id,
      message_id: ctx.message_id,
    },
  }];
}

const items = resp.data?.items || [];

function parseContent(raw) {
  if (raw == null) return {};
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(String(raw)); } catch { return {}; }
}

function isExcelName(name) {
  const n = String(name || '').toLowerCase();
  return n.endsWith('.xlsx') || n.endsWith('.xls');
}

let chosen = null;
for (const msg of items) {
  const mid = String(msg.message_id || '');
  if (mid && mid === ctx.message_id) continue;
  if (String(msg.msg_type || '') !== 'file') continue;
  const content = parseContent((msg.body || {}).content ?? msg.content);
  const fileKey = String(content.file_key || '').trim();
  const fileName = String(content.file_name || content.name || '').trim();
  if (!fileKey) continue;
  if (fileName && !isExcelName(fileName)) continue;
  chosen = {
    file_message_id: mid,
    file_key: fileKey,
    file_name: fileName || '(未命名文件)',
  };
  break;
}

if (!chosen) {
  return [{
    json: {
      ready: false,
      fail_reason: '未在群内找到最近的 Excel 文件消息，请先发送 .xlsx/.xls 再发「发票号校验」',
      chat_id: ctx.chat_id,
      message_id: ctx.message_id,
    },
  }];
}

return [{
  json: {
    ready: true,
    chat_id: ctx.chat_id,
    message_id: ctx.message_id,
    file_message_id: chosen.file_message_id,
    file_key: chosen.file_key,
    file_name: chosen.file_name,
  },
}];

const rows = $input.all().map((i) => i.json);
const ctx = $('定位最近Excel文件').first().json;

function cell(row, ...keys) {
  for (const key of keys) {
    if (row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  for (const [k, v] of Object.entries(row || {})) {
    const nk = String(k).replace(/\s+/g, '');
    if (keys.some((want) => nk === String(want).replace(/\s+/g, ''))) {
      if (v != null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
}

const taxMap = {};
const buyerSet = new Set();
for (const row of rows) {
  const no = cell(row, '数电发票号码');
  const buyer = cell(row, '购买方名称', '购方名称');
  if (buyer) buyerSet.add(buyer);
  if (!no) continue;
  taxMap[no] = {
    status: cell(row, '发票状态') || '',
    risk: cell(row, '发票风险等级') || '',
    buyer,
  };
}

const buyers = [...buyerSet];
const taxCount = Object.keys(taxMap).length;
let fail_reason = '';
if (!taxCount) fail_reason = 'Excel「发票基础信息」中没有有效的数电发票号码';
else if (!buyers.length) fail_reason = 'Excel「发票基础信息」中没有有效的购买方名称';

const payload = {
  ok: !fail_reason,
  fail_reason,
  chat_id: ctx.chat_id,
  message_id: ctx.message_id,
  file_name: ctx.file_name,
  taxMap,
  taxCount,
  buyers,
  buyerCount: buyers.length,
};

const mem = $getWorkflowStaticData('global');
mem.invoiceTaxCheck = payload;

return [{ json: payload }];

const token = $('获取Token').first().json.tenant_access_token;
const baseId = $env.FEISHU_BASE_ID;
const tableId = 'tblNd9zgN7ALihwj';
const first = $json;
const mem = $getWorkflowStaticData('global');
const tax = mem.invoiceTaxCheck || {};
const buyers = Array.isArray(tax.buyers) ? tax.buyers.slice(0, 50) : [];

if (first.code !== 0 && first.code !== undefined) {
  throw new Error(`拉取回票表失败: ${first.msg || JSON.stringify(first)}`);
}

const searchBody = {
  field_names: ['发票号码', '购方名称'],
  filter: {
    conjunction: 'or',
    conditions: buyers.map((b) => ({
      field_name: '购方名称',
      operator: 'is',
      value: [b],
    })),
  },
};

const records = [...(first.data?.items || [])];
let pageToken = first.data?.page_token || '';
let hasMore = Boolean(first.data?.has_more);

while (hasMore && pageToken) {
  const qs = new URLSearchParams({ page_size: '500', page_token: pageToken });
  const url = `https://open.feishu.cn/open-apis/bitable/v1/apps/${baseId}/tables/${tableId}/records/search?${qs}`;
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: searchBody,
    json: true,
  });
  if (resp.code !== 0) {
    throw new Error(`拉取回票表翻页失败: ${resp.msg || JSON.stringify(resp)}`);
  }
  records.push(...(resp.data?.items || []));
  hasMore = Boolean(resp.data?.has_more);
  pageToken = resp.data?.page_token || '';
  if (!hasMore) break;
}

function splitInvoiceNos(raw) {
  if (raw == null) return [];
  return String(raw).split(/[，,;；\s]+/).map((s) => s.trim()).filter(Boolean);
}

function fieldText(fields, name) {
  const v = fields?.[name];
  if (v == null) return '';
  if (typeof v === 'string' || typeof v === 'number') return String(v);
  if (Array.isArray(v)) {
    return v.map((x) => {
      if (x == null) return '';
      if (typeof x === 'string' || typeof x === 'number') return String(x);
      if (typeof x === 'object') return String(x.text || x.name || x.value || '');
      return '';
    }).filter(Boolean).join('，');
  }
  if (typeof v === 'object') return String(v.text || v.name || v.value || '');
  return String(v);
}

const bitableMap = {};
for (const rec of records) {
  const recordId = rec.record_id || rec.id;
  if (!recordId) continue;
  for (const no of splitInvoiceNos(fieldText(rec.fields || {}, '发票号码'))) {
    bitableMap[no] = recordId;
  }
}

return [{
  json: {
    chat_id: tax.chat_id,
    message_id: tax.message_id,
    file_name: tax.file_name,
    taxMap: tax.taxMap || {},
    taxCount: tax.taxCount || 0,
    buyers,
    buyerCount: buyers.length,
    bitableMap,
    bitableInvoiceCount: Object.keys(bitableMap).length,
    bitableRecordCount: records.length,
  },
}];

const data = $json;
const taxMap = data.taxMap || {};
const bitableMap = data.bitableMap || {};

const problemsByRecord = {};
for (const [no, recordId] of Object.entries(bitableMap)) {
  const tax = taxMap[no];
  if (!tax) {
    if (!problemsByRecord[recordId]) problemsByRecord[recordId] = [];
    problemsByRecord[recordId].push(`未找到:${no}`);
    continue;
  }
  if (tax.status !== '正常' || tax.risk !== '正常') {
    if (!problemsByRecord[recordId]) problemsByRecord[recordId] = [];
    problemsByRecord[recordId].push(`状态异常(${tax.status || '-'}/${tax.risk || '-'}):${no}`);
  }
}

const updates = Object.entries(problemsByRecord).map(([record_id, parts]) => ({
  record_id,
  fields: { 税务系统状态: parts.join('；') },
}));

const problemCount = updates.length;
const payload = {
  chat_id: data.chat_id,
  message_id: data.message_id,
  file_name: data.file_name,
  taxCount: data.taxCount,
  bitableInvoiceCount: data.bitableInvoiceCount,
  bitableRecordCount: data.bitableRecordCount,
  problemCount,
  has_updates: problemCount > 0,
  updates,
  reply_text: `校验完成：${problemCount} 条有问题`,
};

const mem = $getWorkflowStaticData('global');
mem.invoiceTaxCompare = payload;

return [{ json: payload }];

const mem = $getWorkflowStaticData('global');
const cmp = mem.invoiceTaxCompare || $json;
const updateResp = $json;
let replyText = cmp.reply_text || `校验完成：${cmp.problemCount || 0} 条有问题`;

if (cmp.has_updates) {
  if (updateResp.code !== 0 && updateResp.code !== undefined) {
    replyText = `${replyText}（回写失败: ${updateResp.msg || 'unknown'}）`;
  }
}

return [{
  json: {
    message_id: cmp.message_id,
    reply_text: replyText,
    problemCount: cmp.problemCount || 0,
  },
}];

const cmp = $json;
return [{
  json: {
    message_id: cmp.message_id,
    reply_text: cmp.reply_text,
    problemCount: cmp.problemCount,
  },
}];
